files.content:
.table{
  width:100%;
  border-collapse:collapse;
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
  overflow:hidden;
  font-size:var(--t-small);
  color:var(--obsidian-100);
}
.table th, .table td{
  text-align:left;
  padding:var(--s-3) var(--s-4);
  border-bottom:var(--bw-1) solid var(--obsidian-800);
}
.table th{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
  background:var(--obsidian-850);
  font-weight:500;
}
.table tr:last-child td{
  border-bottom:0;
}
.table-scroll{
  overflow-x:auto;
  max-width:100%;
}
.table tbody tr:has(.table-row-link){
  position:relative;
  cursor:pointer;
  transition:background var(--d-quick) var(--ease-standard);
}
.table tbody tr:has(.table-row-link):hover{
  background:var(--obsidian-850);
}
.table tbody tr:has(.table-row-link):active{
  background:var(--obsidian-800);
}
.table-row-link{
  color:inherit;
  text-decoration:none;
}
.table-row-link::after{
  content:"";
  position:absolute;
  inset:0;
}
.table-row-link:focus-visible{
  outline:none;
}
.table tbody tr:has(.table-row-link:focus-visible){
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--focus-width));
  box-shadow:var(--ring-halo);
}
.table code{
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  color:var(--primary-400);
  background:var(--obsidian-850);
  padding:var(--s-0-5) var(--s-1);
  border-radius:var(--r-sm);
  letter-spacing:var(--tr-mono);
}
.table th:has(> .table-sort){
  padding:0;
}
.table th[aria-sort]{
  background:var(--obsidian-800);
  color:var(--obsidian-200);
}
.table-sort{
  display:flex;
  align-items:center;
  gap:var(--s-2);
  width:100%;
  padding:var(--s-3) var(--s-4);
  background:transparent;
  border:0;
  font:inherit;
  letter-spacing:inherit;
  text-transform:inherit;
  text-align:inherit;
  color:inherit;
  cursor:pointer;
}
.table-sort:hover{
  color:var(--obsidian-200);
}
.table-sort:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--s-0-5));
  box-shadow:var(--ring-halo);
}
@media (max-width: 900px){
  .table{
    font-size:var(--t-caption);
  }
  .table th, .table td{
    padding:var(--s-2) var(--s-3);
  }
}
.table{
  width:min(100%, calc(var(--s-32) * 2.5));
}
